<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { UserRound, ShieldCheck, Mail, ArrowLeft, Check } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import SmsCodeFields from '../components/SmsCodeFields.vue'
import { useAuthStore } from '../stores/auth'
import { formatApiDate } from '../utils/date'
import api from '../services/api'
const auth = useAuthStore(), router = useRouter(), tab = ref('profile'), busy = ref(false), loading = ref(true), error = ref(''), account = ref<any>(null)
const profile = reactive({ display_name:'', avatar_url:'' }), security = reactive({ current_password:'', password:'', confirm:'' })
const contact = reactive({ email:'', current_password:'' }), mobile = reactive({ phone:'', code:'', current_password:'' })
async function load() { error.value = ''; loading.value = true; try { account.value = (await api.get('/account')).data; profile.display_name = account.value.display_name || account.value.username; profile.avatar_url = account.value.avatar_url || ''; contact.email = account.value.email } catch (e:any) { error.value=e.message } finally { loading.value=false } }
async function save(kind:string) {
  if (busy.value) return
  error.value = ''
  if (kind==='password' && security.password!==security.confirm) { error.value='两次输入的新密码不一致'; return }
  busy.value = true
  try {
    const response = kind==='profile' ? await api.patch('/account/profile',{display_name:profile.display_name.trim(),avatar_url:profile.avatar_url.trim() || null}) : await api.post(`/account/${kind}`,kind==='password' ? {current_password:security.current_password,password:security.password} : kind==='email' ? contact : mobile)
    ElMessage.success(response.data.message)
    if (kind==='profile') { await auth.hydrate(); await load() }
    else { auth.logout(); await router.replace('/auth') }
  } catch (e:any) { error.value=e.message } finally { busy.value=false }
}
onMounted(load)
onUnmounted(() => { security.current_password=''; security.password=''; security.confirm=''; contact.current_password=''; mobile.current_password=''; mobile.code='' })
</script>
<template><main class="page tool-page"><header class="library-heading"><div><p class="eyebrow">你的创作身份</p><h1>个人中心</h1><p>管理个人资料与登录方式，让作品始终留在自己的空间。</p></div><RouterLink class="library-button quiet" to="/workspace"><ArrowLeft :size="15" />返回工作台</RouterLink></header><p v-if="error" class="library-error" role="alert">{{ error }}</p><div v-if="loading" class="library-empty">正在读取账号…</div><div v-else-if="account" class="account-layout"><aside class="tool-card account-summary"><div class="account-portrait"><img v-if="account.avatar_url" :src="account.avatar_url" alt="个人头像" @error="($event.target as HTMLImageElement).style.display='none'" /><UserRound :size="34" /></div><h2>{{ account.display_name || account.username }}</h2><p>{{ account.phone ? `手机账号 · ${account.phone}` : account.username }}</p><span class="tool-badge"><Check :size="13" />独立创作空间</span><dl class="tool-facts"><div><dt>账号编号</dt><dd>#{{ account.id }}</dd></div><div><dt>加入时间</dt><dd>{{ formatApiDate(account.created_at) }}</dd></div></dl><RouterLink class="text-link" to="/library">查看我的模型资产 →</RouterLink></aside><section class="tool-card account-content"><div class="tool-tabs" role="group" aria-label="个人中心内容"><button v-for="item in [{id:'profile',name:'个人资料',icon:UserRound},{id:'security',name:'密码安全',icon:ShieldCheck},{id:'contact',name:'联系方式',icon:Mail}]" :key="item.id" :aria-pressed="tab===item.id" :disabled="busy" @click="tab=item.id; error='' "><component :is="item.icon" :size="16" />{{ item.name }}</button></div><div class="tool-tab-content" :key="tab"><form v-if="tab==='profile'" class="tool-form" @submit.prevent="save('profile')"><h2>让你的作品拥有署名</h2><p class="tool-hint">昵称用于展示，手机号仍用于登录。</p><label>创作者昵称<input v-model="profile.display_name" class="library-input" required maxlength="40" :disabled="busy" /></label><label>头像图片链接 <span class="tool-optional">选填</span><input v-model="profile.avatar_url" class="library-input" type="url" maxlength="500" placeholder="https://…" :disabled="busy" /></label><button class="library-button primary-action" :disabled="busy || !profile.display_name.trim()">{{ busy ? '保存中…' : '保存个人资料' }}</button></form><form v-else-if="tab==='security'" class="tool-form" @submit.prevent="save('password')"><h2>更新你的登录密码</h2><p class="tool-hint">修改成功后，所有设备都需要重新登录。</p><label>当前密码<input v-model="security.current_password" class="library-input" required type="password" autocomplete="current-password" minlength="8" maxlength="128" :disabled="busy" /></label><label>新密码<input v-model="security.password" class="library-input" required type="password" autocomplete="new-password" minlength="8" maxlength="128" placeholder="8–128 位密码" :disabled="busy" /></label><label>再次输入新密码<input v-model="security.confirm" class="library-input" required type="password" autocomplete="new-password" minlength="8" maxlength="128" :disabled="busy" /></label><div class="library-actions"><button class="library-button primary-action" :disabled="busy">{{ busy ? '更新中…' : '修改密码并重新登录' }}</button><RouterLink class="text-link" to="/reset-password">忘记当前密码？</RouterLink></div></form><div v-else class="tool-contact-sections"><form class="tool-form" @submit.prevent="save('email')"><h2>联系邮箱</h2><p class="tool-hint">邮箱可用于密码登录，当前不提供邮箱验证或邮件找回。更换后需要重新登录。</p><label>邮箱地址<input v-model="contact.email" class="library-input" required type="email" autocomplete="email" maxlength="100" :disabled="busy" /></label><label>当前密码<input v-model="contact.current_password" class="library-input" required type="password" autocomplete="current-password" minlength="8" maxlength="128" :disabled="busy" /></label><button class="library-button" :disabled="busy">更新邮箱</button></form><form class="tool-form" @submit.prevent="save('phone')"><h2>{{ account.phone ? '更换手机号码' : '绑定手机号码' }}</h2><p class="tool-hint">验证新手机号并填写当前密码。完成后用新手机号登录，项目与作品保持关联。</p><SmsCodeFields v-model:phone="mobile.phone" v-model:code="mobile.code" purpose="bind_phone" :disabled="busy" /><label>当前密码<input v-model="mobile.current_password" class="library-input" required type="password" autocomplete="current-password" minlength="8" maxlength="128" :disabled="busy" /></label><button class="library-button" :disabled="busy">验证并更新手机号</button></form></div></div></section></div><button v-else class="library-button" @click="load">重新读取账号</button></main></template>
